// Lấy toàn bộ input items.
// item[0] sẽ là output từ AI Agent (chứa chuỗi JSON outline)
// item[1] sẽ là output từ id gg (chứa các IDs folder/spreadsheet)
const inputItems = $input.all();

// --- Xử lý Item 1 (Outline từ AI Agent) ---
let parsedOutlineData;
// Kiểm tra xem có ít nhất 1 item input không và item đầu tiên có thuộc tính json.output là string không
if (inputItems.length > 0 && typeof inputItems[0].json.output === 'string') {
  const rawOutputString = inputItems[0].json.output;
  // Làm sạch chuỗi JSON (loại bỏ ```json\n và \n```)
  const cleanedJsonString = rawOutputString.replace(/^```json\s*/, '').replace(/\s*```$/, '').trim();

  try {
    // Parse chuỗi JSON thành mảng các đối tượng dàn ý
    parsedOutlineData = JSON.parse(cleanedJsonString);
    // Kiểm tra xem kết quả parse có phải là mảng không
    if (!Array.isArray(parsedOutlineData)) {
        throw new Error("Kết quả parse outline không phải là một mảng.");
    }
    console.log("Parsed outline data successfully:", parsedOutlineData.length, "items."); // Debug
  } catch (e) {
    // Bắt lỗi nếu parse JSON outline thất bại
    throw new Error("Lỗi khi phân tích cú pháp JSON outline: " + e.message);
  }
} else {
  // Xử lý trường hợp input không đúng định dạng
  throw new Error("Đầu vào không có item đầu tiên hoặc thuộc tính 'output' chứa chuỗi JSON outline.");
}

// --- Xử lý Item 2 (IDs từ id gg) ---
let folderImgId = '';
let folderMp3Id = '';
let folderTextId = '';
let textSaveId = '';

console.log("Total input items:", inputItems.length); // Debug: Số lượng item đầu vào

// Kiểm tra xem có item thứ 2 không và nó có thuộc tính .json không
if (inputItems.length > 1 && inputItems[1].json) {
    console.log("Found input item 2. JSON content:", inputItems[1].json); // Debug: Xem nội dung JSON item 2
    const secondInputItemJson = inputItems[1].json;
    // Lấy các giá trị ID dựa trên tên key từ node id gg
    // Sử dụng ?? '' để đảm bảo kết quả là chuỗi rỗng nếu key không tồn tại hoặc giá trị là null/undefined
    folderImgId = secondInputItemJson['folder img'] ?? '';
    folderMp3Id = secondInputItemJson['folder mp3'] ?? '';
    folderTextId = secondInputItemJson['Folder text'] ?? ''; // Chú ý chữ hoa 'F'
    textSaveId = secondInputItemJson['Text save'] ?? '';
    console.log(`Read IDs from item 2: folderImgId="${folderImgId}", folderMp3Id="${folderMp3Id}", folderTextId="${folderTextId}", textSaveId="${textSaveId}"`); // Debug: Kiểm tra giá trị sau khi đọc
} else {
    console.warn("Cảnh báo: Không tìm thấy item thứ 2 (từ id gg) hoặc không có JSON. Các trường ID sẽ rỗng.");
}

// --- Tạo Output Items bằng cách map qua parsedOutlineData và thêm các IDs ---
// Đảm bảo parsedOutlineData là mảng trước khi map (lớp kiểm tra bổ sung)
if (!Array.isArray(parsedOutlineData)) {
     throw new Error("Lỗi nội bộ: Dữ liệu dàn ý không phải là mảng sau khi xử lý (kiểm tra sau parse).");
}

const finalOutput = parsedOutlineData.map((outlineItem, index) => {
  // Lấy title và description từ mỗi item trong mảng dàn ý đã parse
  // Kiểm tra xem item có phải là object và có thuộc tính title/description không
  const title = (outlineItem && typeof outlineItem === 'object' && outlineItem.title !== undefined) ? outlineItem.title : "Không có tiêu đề";
  const description = (outlineItem && typeof outlineItem === 'object' && outlineItem.description !== undefined) ? outlineItem.description : "Không có mô tả";

  // Tạo object JSON cho mỗi item output
  const outputItemJson = {
    index: index + 1, // Chỉ mục 1-based
    title: title,
    description: description,
    // Thêm các IDs từ item thứ 2 (inputItems[1]) vào mỗi item output
    folderImgId: folderImgId,
    folderMp3Id: folderMp3Id,
    folderTextId: folderTextId,
    textSaveId: textSaveId
  };

  // Mỗi item trong output của Code node cần có cấu trúc { json: { ... data ... } }
  return {
    json: outputItemJson
  };
});

console.log("Final output generated:", finalOutput.length, "items."); // Debug: Số lượng item output cuối cùng

// Trả về mảng các item output
return finalOutput;

const items = $input.all();

let text = '';
let img = '';
let mp3 = '';

items.forEach(item => {
  const name = item.json.name.toLowerCase();
  const id = item.json.id;

  if (name.includes('text')) {
    text = id;
  } else if (name.includes('img')) {
    img = id;
  } else if (name.includes('mp3')) {
    mp3 = id;
  }
});

return {
  text: text,
  img: img,
  mp3: mp3
};

// Lấy tất cả các item từ đầu vào
const items = $('Google Sheets7').all();

// Lấy số lượng ảnh (phần cần chia) từ một node trước đó.
// Giả sử bạn có một node tên là "Set Image Count" và nó trả về một giá trị trong trường 'count'.
// Nếu không có, bạn có thể đặt giá trị cố định ở đây.
const numberOfImages = $input.first().json.Imgs;

// 1. Gộp tất cả nội dung từ trường "output" lại thành một chuỗi văn bản duy nhất.
// Chúng ta sẽ dùng một khoảng trắng để nối các đoạn lại với nhau.
const fullText = items.map(item => item.json.output).join(' ');

// 2. Chia văn bản thành các từ để tính toán chính xác.
const words = fullText.split(/\s+/); // Tách theo bất kỳ khoảng trắng nào (space, tab, newline)
const totalWords = words.length;

// 3. Tính toán số từ cho mỗi phần.
const wordsPerPart = Math.floor(totalWords / numberOfImages);

// Mảng để lưu trữ kết quả cuối cùng
const result = [];

// 4. Lặp và chia văn bản thành các phần.
for (let i = 0; i < numberOfImages; i++) {
  // Tính toán chỉ số bắt đầu và kết thúc cho mỗi phần trong mảng 'words'
  const startIndex = i * wordsPerPart;

  // Đối với phần cuối cùng, lấy tất cả các từ còn lại để tránh bỏ sót do làm tròn.
  const endIndex = (i === numberOfImages - 1) ? totalWords : (i + 1) * wordsPerPart;

  // Lấy các từ cho phần hiện tại và nối chúng lại thành một chuỗi.
  const partText = words.slice(startIndex, endIndex).join(' ');

  // Tạo một đối tượng mới cho mỗi phần và thêm vào mảng kết quả.
  // Bạn có thể tùy chỉnh cấu trúc đối tượng này theo ý muốn.
  result.push({
    part: i + 1, // Số thứ tự của phần
    text: partText, // Nội dung văn bản của phần đó
    word_count: words.slice(startIndex, endIndex).length // Số lượng từ thực tế của phần này
  });
}

// 5. Trả về kết quả dưới dạng JSON.
// n8n sẽ tự động lấy kết quả trả về từ đây để làm đầu ra cho node này.
return result;
